MOTIF_NAME = 'piece_in_enemy_territory'
MOTIF_DESCRIPTION = 'Side to move has at least one piece positioned on the opponent half of the board (ranks 4-7 for White, ranks 0-3 for Black).'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    for piece_type in [chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN, chess.KING]:
        for sq in board.pieces(piece_type, stm):
            rank = chess.square_rank(sq)
            if stm:
                if rank >= 4:
                    return True
            else:
                if rank <= 3:
                    return True
    return False
